// Generates src/brand-css.generated.ts from src/brand.css so Workers can import the CSS as a string
// (esbuild in wrangler and vitest both handle a plain TS module; neither agrees on CSS imports).
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, URL } from "node:url";
import process from "node:process";

const dir = fileURLToPath(new URL("../src/", import.meta.url));
const css = readFileSync(dir + "brand.css", "utf8");
const out =
  "// GENERATED by scripts/gen-css.mjs from brand.css. Do not edit by hand.\n" +
  `export const brandCss = ${JSON.stringify(css)};\n`;
writeFileSync(dir + "brand-css.generated.ts", out);
process.stdout.write("brand-css.generated.ts written (" + css.length + " bytes of CSS)\n");
